const canvas=document.getElementById('bgCanvas'),ctx=canvas.getContext('2d');function rs(){canvas.width=innerWidth;canvas.height=innerHeight}rs();addEventListener('resize',rs);
let blobs=[{x:0.2,y:0.2,r:450,c1:'255,42,109'},{x:0.8,y:0.3,r:500,c1:'120,80,255'},{x:0.5,y:0.85,r:600,c1:'255,90,140'}];
let pts=[];for(let i=0;i<60;i++)pts.push({x:Math.random()*innerWidth,y:Math.random()*innerHeight,vx:(Math.random()-0.5)*0.7,vy:(Math.random()-0.5)*0.7,r:Math.random()*2+0.5});
function anim(){ctx.clearRect(0,0,canvas.width,canvas.height);let g=ctx.createLinearGradient(0,0,canvas.width,canvas.height);g.addColorStop(0,'#1a0a14');g.addColorStop(0.5,'#0b0b1a');g.addColorStop(1,'#0f0a1a');ctx.fillStyle=g;ctx.fillRect(0,0,canvas.width,canvas.height);let t=Date.now()*0.0005;blobs.forEach((b,i)=>{let x=b.x*canvas.width+Math.sin(t+i)*70;let y=b.y*canvas.height+Math.cos(t*0.8+i)*50;let rg=ctx.createRadialGradient(x,y,0,x,y,b.r);rg.addColorStop(0,'rgba('+b.c1+',0.32)');rg.addColorStop(1,'rgba('+b.c1+',0)');ctx.fillStyle=rg;ctx.beginPath();ctx.arc(x,y,b.r,0,Math.PI*2);ctx.fill();});pts.forEach((a,i)=>{a.x+=a.vx;a.y+=a.vy;if(a.x<0||a.x>canvas.width)a.vx*=-1;if(a.y<0||a.y>canvas.height)a.vy*=-1;ctx.beginPath();ctx.arc(a.x,a.y,a.r,0,6.28);ctx.fillStyle='rgba(255,140,180,0.55)';ctx.fill();pts.slice(i+1).forEach(b=>{let d=Math.hypot(a.x-b.x,a.y-b.y);if(d<110){ctx.strokeStyle='rgba(255,100,150,'+(0.1*(1-d/110))+')';ctx.lineWidth=0.5;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}})});requestAnimationFrame(anim)}anim();
const heartsDiv=document.getElementById('hearts');function createHeart(){let h=document.createElement('div');h.className='heart';h.innerText=Math.random()>0.5?'💖':'💗';h.style.left=Math.random()*100+'vw';h.style.animationDuration=(7+Math.random()*8)+'s';h.style.fontSize=(12+Math.random()*16)+'px';heartsDiv.appendChild(h);setTimeout(()=>h.remove(),15000);}setInterval(createHeart,700);

